/* Reset and layout */
:root{--bg:#0f1724;--panel:#0b1220;--accent:#7c3aed;--muted:#9aa4b2;--glass:rgba(255,255,255,0.04);--btn:#111827;--danger:#ef4444;--success:#10b981}
*{box-sizing:border-box;font-family:Inter,ui-sans-serif,system-ui,-apple-system,'Segoe UI',Roboto,'Helvetica Neue',Arial}
html,body,#root{height:100%;margin:0;background:linear-gradient(180deg,#071026 0%, #071726 100%);color:#e6eef8}
.container{max-width:1100px;margin:28px auto;padding:20px;display:grid;grid-template-columns:1fr 360px;gap:20px}
.panel{background:linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));border:1px solid rgba(255,255,255,0.04);padding:18px;border-radius:12px;box-shadow:0 6px 30px rgba(2,6,23,0.6)}
.calculator{display:flex;flex-direction:column;gap:14px}
.display{background:var(--glass);padding:18px;border-radius:10px;display:flex;flex-direction:column;gap:8px}
.display .secondary{font-size:13px;color:var(--muted)}
.display input{background:transparent;border:none;color:#e6eef8;font-size:28px;font-weight:600;outline:none;width:100%;caret-color:var(--accent)}
.keypad{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}
.btn{background:linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));border:1px solid rgba(255,255,255,0.03);color:#e6eef8;padding:14px;border-radius:8px;font-size:16px;cursor:pointer;transition:transform .06s, box-shadow .06s}
.btn:active{transform:translateY(1px)}
.btn.operator{background:linear-gradient(180deg, rgba(124,58,237,0.12), rgba(124,58,237,0.06));border:1px solid rgba(124,58,237,0.18);box-shadow:0 6px 14px rgba(124,58,237,0.06)}
.btn.wide{grid-column:span 2}
.btn.warn{background:linear-gradient(180deg, rgba(239,68,68,0.12), rgba(239,68,68,0.06));border:1px solid rgba(239,68,68,0.12)}
.controls{display:flex;gap:8px}
.metrics-panel{display:flex;flex-direction:column;height:100%;gap:12px}
.metrics-header{display:flex;align-items:center;justify-content:space-between}
.metrics-list{display:grid;gap:8px;overflow:auto;padding-right:6px}
.metric-card{background:linear-gradient(180deg, rgba(255,255,255,0.015), rgba(255,255,255,0.01));border:1px solid rgba(255,255,255,0.03);padding:10px;border-radius:8px;display:flex;align-items:center;justify-content:space-between;gap:8px}
.metric-meta{display:flex;flex-direction:column}
.metric-key{font-size:13px;color:var(--muted)}
.metric-val{font-weight:600;font-size:15px}
.metric-actions{display:flex;gap:8px}
.metric-btn{background:transparent;border:1px dashed rgba(255,255,255,0.04);padding:8px 10px;border-radius:8px;color:var(--muted);cursor:pointer}
.metric-btn.primary{border-style:solid;background:linear-gradient(90deg, rgba(124,58,237,0.12), rgba(16,185,129,0.02));color:#e6eef8}
.small-muted{font-size:12px;color:var(--muted)}
.footer{display:flex;align-items:center;justify-content:space-between;font-size:13px;color:var(--muted)}
.copy-btn{background:transparent;border:1px solid rgba(255,255,255,0.03);padding:6px 10px;border-radius:8px;color:var(--muted);cursor:pointer}
@media(max-width:980px){.container{grid-template-columns:1fr;padding:12px}.metrics-panel{order:2}.panel{padding:12px}}

