/* Reusable helper functions for the calculator UI */
function formatCompact(n){
  if (n === null || n === undefined || isNaN(n)) return String(n);
  const abs = Math.abs(n);
  if (abs >= 1e12) return (n/1e12).toFixed(2).replace(/\.00$/,'') + 'T';
  if (abs >= 1e9) return (n/1e9).toFixed(2).replace(/\.00$/,'') + 'B';
  if (abs >= 1e6) return (n/1e6).toFixed(2).replace(/\.00$/,'') + 'M';
  if (abs >= 1e3) return (n/1e3).toFixed(2).replace(/\.00$/,'') + 'k';
  return Number(n).toString();
}

function safeEvalExpression(expr){
  // Replace typographic operators and remove disallowed chars
  const cleaned = String(expr).replace(/×|\u00D7/g,'*').replace(/÷|\u00F7/g,'/').replace(/−/g,'-');
  // Allow digits, parentheses, operators, decimal point, spaces
  if (!/^[0-9+\-*/()., \t]+$/.test(cleaned)){
    throw new Error('Invalid characters in expression');
  }
  // Prevent sequences like 2..3 or malicious code by only allowing valid patterns
  try{
    // Use Function constructor for arithmetic only
    const fn = new Function('return (' + cleaned + ')');
    const v = fn();
    if (typeof v === 'number' && isFinite(v)) return v;
    throw new Error('Result is not a finite number');
  }catch(e){
    throw new Error('Could not evaluate expression');
  }
}

function insertAtCursor(inputEl, text){
  // Insert text at current caret position in the input
  const start = inputEl.selectionStart || 0;
  const end = inputEl.selectionEnd || 0;
  const before = inputEl.value.slice(0, start);
  const after = inputEl.value.slice(end);
  const newVal = before + text + after;
  inputEl.value = newVal;
  const cursor = start + text.length;
  inputEl.setSelectionRange(cursor, cursor);
  inputEl.focus();
}

function setDisplayValue(inputEl, text){
  inputEl.value = text;
  inputEl.setSelectionRange(text.length, text.length);
  inputEl.focus();
}

function parseNumericValueForInsert(n){
  // Convert a numeric value into a sanitized string for insertion (no commas)
  if (typeof n === 'number') return String(n);
  return String(n).replace(/,/g,'');
}

