/* Initialization: wire up buttons, metrics, and keyboard support */
(function initCalculator(){
  const display = document.getElementById('calc-display');
  const preview = document.getElementById('preview');
  const metricsList = document.getElementById('metrics-list');

  // Sample company data
  const companies = [
    {
      name: 'Acme Corp',
      metrics: [
        { key: 'Revenue', value: 12300000 },
        { key: 'EBITDA', value: 2100000 },
        { key: 'Active Users', value: 1250000 }
      ]
    },
    {
      name: 'Beta LLC',
      metrics: [
        { key: 'Revenue', value: 3450000 },
        { key: 'Customers', value: 42000 },
        { key: 'MQLs', value: 8700 }
      ]
    },
    {
      name: 'Gamma Inc',
      metrics: [
        { key: 'ARR', value: 48500000 },
        { key: 'Churn %', value: 0.023 },
        { key: 'Avg. Order', value: 89.5 }
      ]
    }
  ];

  // Populate metric cards
  companies.forEach(company => {
    const header = document.createElement('div');
    header.style.marginTop = '8px';
    header.style.fontWeight = '600';
    header.textContent = company.name;
    metricsList.appendChild(header);

    company.metrics.forEach(m => {
      const card = document.createElement('div');
      card.className = 'metric-card';

      const meta = document.createElement('div');
      meta.className = 'metric-meta';
      const k = document.createElement('div'); k.className = 'metric-key'; k.textContent = m.key;
      const v = document.createElement('div'); v.className = 'metric-val'; v.textContent = formatCompact(m.value);
      meta.appendChild(k); meta.appendChild(v);

      const actions = document.createElement('div');
      actions.className = 'metric-actions';

      const insertBtn = document.createElement('button');
      insertBtn.className = 'metric-btn primary';
      insertBtn.title = 'Insert value into expression';
      insertBtn.textContent = 'Insert';
      insertBtn.dataset.value = parseNumericValueForInsert(m.value);
      insertBtn.addEventListener('click', () => {
        // Insert numeric literal (if percent like 0.023, insert 0.023)
        const val = insertBtn.dataset.value;
        // If display currently equals '0', replace it
        if (display.value === '0') setDisplayValue(display, val);
        else insertAtCursor(display, val);
        updatePreview();
      });

      const copyBtn = document.createElement('button');
      copyBtn.className = 'metric-btn';
      copyBtn.textContent = 'Copy';
      copyBtn.title = 'Copy metric raw value';
      copyBtn.addEventListener('click', async () => {
        try{
          await navigator.clipboard.writeText(String(m.value));
          copyBtn.textContent = 'Copied!';
          setTimeout(()=> copyBtn.textContent = 'Copy', 1200);
        }catch(e){
          copyBtn.textContent = 'Failed';
          setTimeout(()=> copyBtn.textContent = 'Copy', 1200);
        }
      });

      actions.appendChild(insertBtn);
      actions.appendChild(copyBtn);

      card.appendChild(meta);
      card.appendChild(actions);
      metricsList.appendChild(card);
    });
  });

  // Helper to update preview from expression
  function updatePreview(){
    const expr = display.value.trim();
    if (!expr) { preview.textContent = '0'; return; }
    try{
      const v = safeEvalExpression(expr);
      preview.textContent = Number.isFinite(v) ? v : '—';
    }catch(e){
      preview.textContent = 'err';
    }
  }

  // Button wiring for keypad
  document.querySelectorAll('.keypad .btn[data-key]').forEach(b => {
    b.addEventListener('click', () => {
      const k = b.dataset.key;
      if (display.value === '0' && /[0-9.]/.test(k)){
        setDisplayValue(display, k);
      } else {
        insertAtCursor(display, k);
      }
      updatePreview();
    });
  });

  // Clear, backspace, parentheses, divide, equals, copy
  document.getElementById('btn-clear').addEventListener('click', ()=>{ setDisplayValue(display,'0'); preview.textContent='0'; });
  document.getElementById('btn-back').addEventListener('click', ()=>{
    const s = display.selectionStart || 0;
    const e = display.selectionEnd || 0;
    if (s === e && s>0){
      display.value = display.value.slice(0,s-1) + display.value.slice(e);
      display.setSelectionRange(s-1,s-1);
    } else {
      display.value = display.value.slice(0,s) + display.value.slice(e);
      display.setSelectionRange(s,s);
    }
    updatePreview();
  });
  document.getElementById('btn-paren').addEventListener('click', ()=>{
    // Toggle insert parentheses intelligently
    const pos = display.selectionStart || 0;
    // If next char is ')', insert '(' else try to balance by inserting ')'
    insertAtCursor(display, '()');
    display.setSelectionRange(pos+1,pos+1);
    updatePreview();
  });
  document.getElementById('btn-div').addEventListener('click', ()=>{ insertAtCursor(display, '/'); updatePreview(); });

  document.getElementById('btn-equals').addEventListener('click', ()=>{
    try{
      const result = safeEvalExpression(display.value);
      setDisplayValue(display, String(result));
      preview.textContent = String(result);
    }catch(e){
      preview.textContent = 'err';
      // brief visual shake
      const d = document.querySelector('.display');
      d.style.transform = 'translateX(-6px)';
      setTimeout(()=> d.style.transform = '', 140);
    }
  });

  document.getElementById('btn-copy').addEventListener('click', async ()=>{
    try{
      await navigator.clipboard.writeText(display.value);
      const btn = document.getElementById('btn-copy');
      btn.textContent = 'Copied';
      setTimeout(()=> btn.textContent = 'Copy', 1000);
    }catch(e){
      alert('Copy failed');
    }
  });

  // Keyboard support
  window.addEventListener('keydown', (ev)=>{
    // Allow typing in the input naturally
    const ignore = ['INPUT','TEXTAREA'];
    if (document.activeElement && ignore.includes(document.activeElement.tagName)){
      // Let input handle it, but update preview on keyup
      return;
    }
    const key = ev.key;
    if (/^[0-9]$/.test(key) || key === '.'){
      ev.preventDefault(); insertAtCursor(display, key); updatePreview(); return;
    }
    if (key === 'Enter' || key === '='){
      ev.preventDefault(); document.getElementById('btn-equals').click(); return;
    }
    if (key === 'Backspace'){
      ev.preventDefault(); document.getElementById('btn-back').click(); return;
    }
    if (key === 'Escape'){
      ev.preventDefault(); document.getElementById('btn-clear').click(); return;
    }
    if (['+','-','/','*','(',')'].includes(key)){
      ev.preventDefault(); insertAtCursor(display, key); updatePreview(); return;
    }
  });

  // Update preview as user types inside the input
  display.addEventListener('input', updatePreview);
  display.addEventListener('keyup', updatePreview);

  // Initialize preview
  updatePreview();
})();
